-- scripts/add_potamoi.sql
-- Greek river-gods (Potamoi), sons of Oceanus, from the river catalogue of Hesiod
-- Theogony 337-345 (Evelyn-White). One shared catalogue quote per river; held names skipped.

BEGIN;

ON CONFLICT (entity_id) DO NOTHING;

ON CONFLICT (citation_id) DO UPDATE SET quote=EXCLUDED.quote;

COMMIT;
